// Scheduled posts, post details, approvals, and account connections.
// Publishing queue: posts SignalDesk publishes itself, shown on the calendar, Command Center, and approvals.
const POST_STATUS_LABELS={pending_approval:'In Review',scheduled:'Scheduled',publishing:'Publishing',published:'Published',partial:'Partly published',failed:'Failed',canceled:'Canceled'};
const JOB_STATUS_LABELS={held:'Waiting for approval',manual_due:'Time to post',queued:'Scheduled',publishing:'Publishing now',published:'Published',failed:'Failed',unknown:'Check the account',canceled:'Canceled'};
const WORKER_GRACE_MS=5*60000;
let serverPostsLoading=false,serverPostsLoadedAt=0,openPostId=null;
const CLIENT_COLOR_COUNT=7;
function clientColorIndex(client){if(!client)return 0;const at=clients.findIndex(item=>item.id===client.id);if(at>=0)return at%CLIENT_COLOR_COUNT;let hash=0;for(const ch of String(client.id||client.name||''))hash=(hash*31+ch.charCodeAt(0))>>>0;return hash%CLIENT_COLOR_COUNT;}
function clientStyle(client){const index=clientColorIndex(client);return{cls:`event-c${index}`,color:`cbg-c${index}`};}
// A post's picture for the calendar and lists: the chosen video cover, else its first image (videos without a cover get none).
function postThumbUrl(post){const cover=post?.options?.cover?.url;if(cover)return cover;const first=(post?.media||[]).map(item=>typeof item==='string'?item:item?.url).find(url=>url&&/^https:\/\//i.test(url)&&!VIDEO_FILE.test(url));return first||'';}
// Who did what on a post, so teammates can see who to ask: "Scheduled by Phil · Approved by Sam".
let teamNames={};
function personLabel(id){if(!id)return'';if(id===activeUser?.id)return'you';return teamNames[id]||'a teammate';}
function postPeopleText(post){if(!post)return'';if(post.source==='autopilot')return post.approvedBy?`Autopilot · approved by ${personLabel(post.approvedBy)}`:'Autopilot';const parts=[];if(post.createdBy)parts.push(`${post.status==='pending_approval'?'Submitted':'Scheduled'} by ${personLabel(post.createdBy)}`);if(post.approvedBy&&post.approvedBy!==post.createdBy)parts.push(`approved by ${personLabel(post.approvedBy)}`);const text=parts.join(' · ');return text.charAt(0).toUpperCase()+text.slice(1);}
function serverCalendarPosts(list=serverPosts){return list.filter(post=>post.status!=='canceled').map(post=>{const when=new Date(post.scheduledFor),client=clients.find(item=>item.id===post.clientId),style=clientStyle(client),name=client?.name||'Client';return{serverId:post.id,date:localIsoDate(when),day:when.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'}).toUpperCase(),time:when.toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}),at:when.getTime(),client:name,initials:client?.initials||name.split(' ').map(word=>word[0]).join('').slice(0,2),color:style.color,cls:style.cls,title:post.title||'Untitled post',thumb:postThumbUrl(post),by:[postPeopleText(post),post.assignedTo?`assigned to ${personLabel(post.assignedTo)}`:''].filter(Boolean).join(' · '),assignedTo:post.assignedTo||null,pillar:post.options?.pillar||'',channel:post.jobs.filter(job=>job.status!=='canceled').map(jobLabel).join(', ')||'Social',platforms:[...new Set(post.jobs.filter(job=>job.status!=='canceled').map(job=>job.platform))],status:POST_STATUS_LABELS[post.status]||post.status,autopilot:post.source==='autopilot',campaign:post.campaign,movable:currentRole==='admin'&&['pending_approval','scheduled'].includes(post.status)&&!post.jobs.some(job=>['publishing','published'].includes(job.status))};});}
function upcomingPosts(){if(!cloudFeaturesAvailable())return allPosts();const soon=Date.now()-3600000,server=serverCalendarPosts().filter(post=>post.at>=soon).sort((a,b)=>a.at-b.at);return[...server,...savedPosts.filter(post=>post.status==='Draft')];}
// Posts load from 35 days back to about two months ahead. Paging the calendar further or opening the List widens the
// range (up to about 13 months ahead), read in the API's 100-day windows, so every post shown can also be opened.
let serverPostsUntil=0,serverPostsLoadedThrough=0,serverPostsAgain=false;
function serverPostsRange(){const from=addDays(startOfDay(new Date()),-35);return{from,to:new Date(Math.max(addDays(from,98).getTime(),serverPostsUntil))};}
function serverPostsCover(date){const want=Math.min(date.getTime(),addDays(new Date(),400).getTime());if(want<=serverPostsRange().to.getTime())return false;serverPostsUntil=Math.min(addDays(new Date(want),60).getTime(),addDays(new Date(),400).getTime());loadServerPosts(true);return true;}
async function fetchServerPosts(force=false){if(!cloudFeaturesAvailable())return;if(serverPostsLoading){if(force)serverPostsAgain=true;return;}if(!force&&Date.now()-serverPostsLoadedAt<20000)return;serverPostsLoading=true;try{const{from,to}=serverPostsRange(),pages=[];for(let start=from;start<to;start=addDays(start,98))pages.push(callSocialApi({action:'posts',from:start.toISOString(),to:new Date(Math.min(addDays(start,98).getTime(),to.getTime())).toISOString()}));const results=await Promise.all(pages),byId=new Map();results.forEach(data=>{Object.assign(teamNames,data.people||{});(data.posts||[]).forEach(post=>byId.set(post.id,post));});serverPosts=[...byId.values()];serverPostsLoadedAt=Date.now();serverPostsLoadedThrough=to.getTime();serverPostsError=null;renderUpcoming();renderCalendar();renderApprovals();refreshPostDialog();renderCommandCenter();renderCampaignOptions();renderCommentsPanel();renderStudioUpcoming();drawClients();}catch(error){console.error('Could not load scheduled posts:',error);serverPostsError=error;const list=$('#upcoming-list');if(list&&!serverPostsLoadedAt)list.innerHTML=errorHtml(error,'posts');renderStudioUpcoming();if(typeof calView!=='undefined'&&calView==='list')renderCalendar();}finally{serverPostsLoading=false;if(serverPostsAgain){serverPostsAgain=false;fetchServerPosts(true);}}}
async function loadServerPosts(...args){const result=await fetchServerPosts(...args);applyPendingPostChanges();return result;}
let serverPostsError=null;
RETRY_HANDLERS.posts=()=>loadServerPosts(true);
function toLocalInput(date){const pad=value=>String(value).padStart(2,'0');return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;}
function openPostDialog(id){const dialog=$('#post-dialog');if(!dialog)return;openPostId=id;refreshPostDialog();loadPostNotes(id);loadPostHistory(id);if(!dialog.open)dialog.showModal();const heading=$('#post-dialog-body h2');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}
function jobRowHtml(post,job){const hint=job.status==='failed'&&job.error?explainPublishError(job.platform,job.error,job.errorKind):null,overdue=job.status==='queued'&&Date.parse(job.runAt)<Date.now()-WORKER_GRACE_MS,admin=currentRole==='admin';const detail=job.status==='unknown'?'The connection dropped after the post was sent, so it may already be live. Check the account before posting again.':job.error?job.error:overdue?'Past its time and still waiting. Make sure the publishing worker is scheduled (see the README).':job.status==='queued'&&job.attempts?`Retrying after a temporary problem (attempt ${job.attempts + 1}).`:'';const manualActions=job.provider==='manual'&&job.status==='manual_due'?`<button class="text-button" type="button" data-copy-text="${job.id}">Copy text</button><button class="text-button" type="button" data-send-phone>Send to my phone</button><button class="secondary-button" type="button" data-manual-done="${job.id}">Mark as posted</button>`:job.provider==='manual'&&['queued','held'].includes(job.status)?`<button class="text-button" type="button" data-copy-caption="${escapeHtml(job.platform)}">Copy caption</button><button class="text-button" type="button" data-send-phone>Send to my phone</button>`:'';const comments=job.status==='published'&&job.provider==='direct'&&['facebook','instagram','linkedin'].includes(job.platform)&&admin?`<button class="text-button" type="button" data-job-comments="${job.id}">Comments</button>`:'';const action=!admin?'':job.status==='failed'&&post.jobs.filter(item=>item.status==='failed').length>1?`<button class="secondary-button" type="button" data-retry-job="${job.id}">Retry</button>`:job.status==='unknown'?`<button class="secondary-button" type="button" data-retry-job="${job.id}" data-confirmed="true">Not live — post again</button>`:'';return `<div class="job-row ${job.status}${overdue?' overdue':''}"><span class="platform-icon ${job.platform}">${escapeHtml(job.provider==='manual'?'⏰':SOCIAL_NETWORKS.find(item=>item[0]===job.platform)?.[2]||'•')}</span><div><b>${escapeHtml(jobLabel(job))}</b><small>${escapeHtml(job.provider==='manual'&&job.status==='queued'?'Reminder scheduled':job.provider==='manual'&&job.status==='published'?'Posted by you':JOB_STATUS_LABELS[job.status]||job.status)}${job.provider==='ayrshare'?' · via Ayrshare':job.provider==='manual'?' · you post this':''}${job.publishedAt?` · ${friendlyWhen(job.publishedAt)}`:''}${typeof job.clicks==='number'?` · ${job.clicks.toLocaleString('en-US')} link click${job.clicks===1?'':'s'}`:''}</small>${hint?`<p class="job-detail"><b>${escapeHtml(hint.why)}</b> ${escapeHtml(hint.fix)}</p><details class="job-raw"><summary>Details</summary><p>${escapeHtml(job.error||'')}</p></details>`:detail?`<p class="job-detail">${escapeHtml(detail)}</p>`:''}</div><div class="job-actions">${job.url?`<a class="secondary-link" href="${escapeHtml(job.url)}" target="_blank" rel="noopener">View ↗</a>`:''}${manualActions}${comments}${action}</div></div>`;}
// A scheduled video post's cover: shown in the post panel, and changeable until the post starts publishing.
function postVideoUrl(post){return[...(post.media||[]),...Object.values(post.platformContent||{}).flatMap(item=>Array.isArray(item?.media)?item.media:[])].find(url=>isVideoMedia({url}));}
function postCoverHtml(post,editable){const video=postVideoUrl(post);if(!video)return'';const url=post.options?.cover?.url,offset=post.options?.cover?.offsetMs;if(!url&&!editable)return'';const state=url&&Number.isInteger(offset)?`Frame at ${(offset/1000).toFixed(1)} s`:url?'Cover photo chosen':Number.isInteger(offset)?`Frame at ${(offset/1000).toFixed(1)} s`:'First frame of the video (default)';return `<div class="post-cover"><div class="cover-thumb">${url?`<img loading="lazy" decoding="async" src="${escapeHtml(url)}" alt="Video cover">`:`<video src="${escapeHtml(video)}#t=${((Number.isInteger(offset)?offset:100)/1000).toFixed(2)}" muted playsinline preload="metadata"></video>`}</div><div class="cover-body"><b>Video cover</b><small>${escapeHtml(state)}</small>${editable?`<div class="cover-actions"><button type="button" class="secondary-button" data-post-cover-frame>Choose a frame</button><button type="button" class="secondary-button" data-post-cover>Choose cover photo</button>${url||Number.isInteger(offset)?'<button type="button" class="text-button" data-post-cover-remove>Remove</button>':''}</div>`:''}</div></div>`;}
async function savePostCover(postId,blob,offsetMs=null){const message=$('#post-dialog-message');if(message)message.textContent='Uploading the cover…';const uploaded=await uploadToStorage(new File([blob],'cover.jpg',{type:'image/jpeg'}),'cover');if(!uploaded){if(message)message.textContent='';return false;}const result=await postAction({action:'set-cover',postId,url:uploaded.url,...(offsetMs!==null?{offsetMs}:{})},offsetMs!==null?'Cover frame saved.':'Cover photo saved.');if(message&&result)message.textContent='';return Boolean(result);}
// The post panel shows the first image or video large, like it will appear, with any others as thumbnails.
function postCardMediaHtml(post){const list=post.media||[];if(!list.length)return'';const first=list[0],big=isVideoMedia({url:first})?`<video src="${escapeHtml(first)}#t=0.1" controls muted playsinline preload="metadata"></video>`:`<img src="${escapeHtml(first)}" alt="${escapeHtml(post.mediaAlt?.[first]||'')}" loading="lazy" referrerpolicy="no-referrer">`;return `<div class="pdc-media">${big}</div>${list.length>1?mediaThumbsHtml(list,{max:8}):''}`;}
function refreshPostDialog(){const dialog=$('#post-dialog'),body=$('#post-dialog-body');if(!dialog||!body||!openPostId)return;const pendingNote=$('#post-note-input')?.value||'';const post=serverPosts.find(item=>item.id===openPostId);if(!post){body.innerHTML=`<p class="option-hint">This post is no longer on the calendar.</p><div class="auth-actions"><button class="secondary-button" type="button" data-close-post>Close</button></div>`;return;}const client=clients.find(item=>item.id===post.clientId),when=new Date(post.scheduledFor),admin=currentRole==='admin',own=post.createdBy===activeUser?.id,pending=post.status==='pending_approval',movable=['pending_approval','scheduled'].includes(post.status)&&!post.jobs.some(job=>['publishing','published'].includes(job.status)),cancelable=(admin&&['pending_approval','scheduled','publishing','partial'].includes(post.status)&&post.jobs.some(job=>['held','queued'].includes(job.status)))||(own&&pending),media=postCardMediaHtml(post),custom=Object.keys(post.platformContent||{}).filter(platform=>post.platformContent[platform]?.text!==undefined),cover=postCoverHtml(post,admin&&movable);
body.innerHTML=`<div class="post-dialog-head"><div><small>${escapeHtml(client?.name||'Client')}${post.source==='autopilot'?' · Autopilot':''}${post.parentId?' · Repost':''}</small><h2>${escapeHtml(post.title||'Untitled post')}</h2><p>${escapeHtml(when.toLocaleString('en-US',{weekday:'long',month:'long',day:'numeric',hour:'numeric',minute:'2-digit'}))} <span class="when-rel">${escapeHtml(relativeWhen(when))}</span></p>${clientTimeNote(client,when)?`<p class="tz-hint">${escapeHtml(clientTimeNote(client,when))}</p>`:''}${postPeopleText(post)?`<p class="post-people">${icon('users','ico-inline')}${escapeHtml(postPeopleText(post))}</p>`:''}${postAssignHtml(post)}${postSeriesHtml(post)}</div><div class="post-dialog-corner"><span class="status ${statusClass(POST_STATUS_LABELS[post.status]||post.status)}">${escapeHtml(POST_STATUS_LABELS[post.status]||post.status)}</span><button class="icon-button post-dialog-x" type="button" data-close-post aria-label="Close">×</button></div></div>
${post.campaign||post.evergreen||post.clientStatus||post.options?.pillar?`<div class="post-dialog-tags">${post.campaign?`<span>Campaign: ${escapeHtml(post.campaign)}</span>`:''}${post.options?.pillar?`<span>Pillar: ${escapeHtml(post.options.pillar)}</span>`:''}${post.evergreen?`<span>${icon('repeat','ico-inline')}Reused</span>`:''}${post.clientStatus?`<span class="${post.clientStatus==='approved'?'good':'bad'}">${post.clientStatus==='approved'?'Client approved':'Client requested changes'}</span>`:''}</div>`:''}<div class="post-dialog-card"><div class="pdc-head"><span class="client-avatar ${clientStyle(client).color}" aria-hidden="true">${escapeHtml(client?.initials||'•')}</span><div><b>${escapeHtml(client?.name||'Client')}</b><small>${escapeHtml(post.jobs.map(jobLabel).join(' · '))}</small></div></div><div class="post-dialog-copy">${escapeHtml(post.text)}</div>${media}</div>${custom.length?`<p class="option-hint">Custom copy for ${escapeHtml(custom.map(platformLabel).join(', '))}.</p>`:''}${cover}
${abCompareHtml(post)}<div class="job-list">${post.jobs.map(job=>jobRowHtml(post,job)).join('')}</div>${post.decisionNote?`<p class="option-hint">Approval note: ${escapeHtml(post.decisionNote)}</p>`:''}<div class="post-notes-section"><h3>Notes</h3><div id="post-notes"></div><form class="post-note-form" id="post-note-form"><input class="field" id="post-note-input" maxlength="2000" placeholder="Add a note for the team. Type @ to mention someone." aria-label="Note" autocomplete="off"><button class="secondary-button" type="submit">Add</button></form></div>
${admin&&movable?`<div class="post-dialog-reschedule"><label class="field-label" for="post-dialog-time">Move to</label><div><input type="datetime-local" id="post-dialog-time" class="field" value="${toLocalInput(when)}"><button class="secondary-button" type="button" data-reschedule-post>Move</button></div></div>`:''}
<p class="auth-message" id="post-dialog-message" role="status"></p>
<details class="post-history-section"><summary>History</summary><div id="post-history"></div></details>
${(()=>{const failedCount=admin?post.jobs.filter(job=>job.status==='failed').length:0,editable=postEditable(post),main=admin&&pending?'approve':failedCount?'retry':editable?'edit':'';const primary=main==='approve'?`<button class="primary-button" type="button" data-approve-post>${icon('check')}Approve</button><button class="secondary-button" type="button" data-reject-post>Request changes</button>`:main==='retry'?`<button class="primary-button" type="button" data-retry-failed>${icon('refresh')}${failedCount>1?`Retry ${failedCount} failed`:'Retry'}</button>`:main==='edit'?`<button class="primary-button" type="button" data-edit-post>${icon('edit')}Edit in Studio</button>`:'';const quiet=[editable&&main!=='edit'?'<button class="text-button" type="button" data-edit-post>Edit in Studio</button>':'','<button class="text-button" type="button" data-duplicate-post>Duplicate</button>',['published','partial'].includes(post.status)&&post.text?`<button class="text-button" type="button" data-refresh-post="${escapeHtml(post.id)}">Reuse with a fresh take</button>`:'',cancelable?cancelButtonsHtml(post,own&&pending&&!admin):''].filter(Boolean).join('');return `<div class="auth-actions post-dialog-actions">${primary}<span class="post-dialog-quiet">${quiet}</span><button class="secondary-button post-dialog-close" type="button" data-close-post>Close</button></div>`;})()}`;if(pendingNote)$('#post-note-input').value=pendingNote;renderPostNotes();renderPostHistory();}
async function postAction(payload,success){const message=$('#post-dialog-message');try{const result=await callSocialApi(payload);if(success)toast(typeof success==='function'?success(result):success);await loadServerPosts(true);return result;}catch(error){if(message)message.textContent=error.message;toast(error.message);return null;}}
async function approveServerPost(id){const result=await postAction({action:'approve',postId:id},result=>result.late?'Approved. Its time had passed, so it publishes in the next minute.':'Approved and scheduled.');return result;}
async function rejectServerPost(id){const note=prompt('What should change? (Optional; the author sees this.)');if(note===null)return null;return postAction({action:'reject',postId:id,note},'Sent back to the author.');}
$('#post-dialog')?.addEventListener('click',async event=>{const dialog=$('#post-dialog');if(event.target===dialog||event.target.closest('[data-close-post]')){dialog.close();return;}const post=serverPosts.find(item=>item.id===openPostId);if(!post)return;if(event.target.closest('[data-edit-post]')){dialog.close();startEditingPost(post);return;}if(event.target.closest('[data-duplicate-post]')){const snapshot=editingPost?null:snapshotDraft();if(editingPost)stopEditing();dialog.close();duplicatePost(post);if(snapshot)offerDraftUndo(snapshot,'Copy loaded, replacing your draft.');return;}const restore=event.target.closest('[data-restore-version]');if(restore){restoreVersion(restore.dataset.restoreVersion);return;}const copyButton=event.target.closest('[data-copy-text]');if(copyButton){const copyJob=post.jobs.find(item=>item.id===copyButton.dataset.copyText);try{await navigator.clipboard.writeText(copyJob?.copyText||post.platformContent?.[copyJob?.platform]?.text||post.text);toast('Post text copied.');}catch{toast('Select the text above and copy it.');}return;}const manualDone=event.target.closest('[data-manual-done]');if(manualDone){const url=prompt('Link to the live post (optional):','');if(url===null)return;await postAction({action:'manual-done',jobId:manualDone.dataset.manualDone,url:url.trim()},'Marked as posted.');return;}const commentsButton=event.target.closest('[data-job-comments]');if(commentsButton){dialog.close();showView('inbox');openJobComments(commentsButton.dataset.jobComments);return;}if(event.target.closest('[data-approve-post]')){await approveServerPost(post.id);return;}if(event.target.closest('[data-reject-post]')){if(await rejectServerPost(post.id))dialog.close();return;}if(event.target.closest('[data-cancel-post]')){const id=post.id,scope=event.target.closest('[data-cancel-post]').dataset.cancelScope||null,ids=scope==='following'?postSeries(post).later.map(item=>item.id):[id];dialog.close();ids.forEach(hidePostLocally);showUndo(ids.length>1?`Canceled ${ids.length} posts in the series.`:`“${post.title||'Post'}” canceled.`,{run:async()=>{const result=await callSocialApi({action:'cancel-post',postId:id,...(scope?{scope}:{})});ids.forEach(item=>hiddenPosts.delete(item));await loadServerPosts(true);if(result.keptPublished)toast('Canceled the rest. Networks it already reached keep the post.');},onUndo:()=>ids.forEach(restorePostLocally),undoneMessage:ids.length>1?'The posts are back on the schedule.':'The post is back on the schedule.'});return;}if(event.target.closest('[data-reschedule-post]')){const value=$('#post-dialog-time').value,when=new Date(value);if(!value||isNaN(when)){$('#post-dialog-message').textContent='Choose a date and time.';return;}await postAction({action:'reschedule-post',postId:post.id,scheduleDate:when.toISOString()},`Moved to ${when.toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}.`);return;}if(event.target.closest('[data-post-cover-frame]')){const id=post.id,video=postVideoUrl(post);openCoverFrames({src:video,start:(post.options?.cover?.offsetMs??0)/1000,save:(blob,offsetMs)=>savePostCover(id,blob,offsetMs),saveFrame:async offsetMs=>Boolean(await postAction({action:'set-cover',postId:id,offsetMs},'Cover frame saved. Instagram and TikTok will use it.'))});return;}if(event.target.closest('[data-post-cover]')){const id=post.id;uploadCoverImage(async blob=>{await savePostCover(id,blob);return false;});return;}if(event.target.closest('[data-post-cover-remove]')){await postAction({action:'set-cover',postId:post.id,url:null},'Cover removed. The video’s first frame is used.');return;}const retryAll=event.target.closest('[data-retry-failed]');if(retryAll){const ids=post.jobs.filter(job=>job.status==='failed').map(job=>job.id);if(!ids.length)return;retryAll.disabled=true;try{for(const id of ids.slice(0,-1))await callSocialApi({action:'retry-job',jobId:id});}catch(error){const message=$('#post-dialog-message');if(message)message.textContent=friendlyError(error);retryAll.disabled=false;return;}await postAction({action:'retry-job',jobId:ids[ids.length-1]},ids.length>1?`${ids.length} networks queued to publish again in the next minute.`:'Queued to publish again in the next minute.');return;}const retry=event.target.closest('[data-retry-job]');if(retry){await postAction({action:'retry-job',jobId:retry.dataset.retryJob,confirmed:retry.dataset.confirmed==='true'},'Queued to publish again in the next minute.');}});
// The close event fires a moment later, so ignore it if another post was opened since.
$('#post-dialog')?.addEventListener('submit',event=>{if(event.target.id==='post-note-form'){event.preventDefault();addPostNote();}});
$('#post-dialog')?.addEventListener('close',()=>{if(!$('#post-dialog').open){openPostId=null;}});
document.addEventListener('click',event=>{const target=event.target.closest('[data-open-post]');if(!target||suppressOpenClick||event.target.closest('a,button:not([data-open-post])'))return;openPostDialog(target.dataset.openPost);});
document.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches?.('[data-open-post][role=button]')){event.preventDefault();openPostDialog(event.target.dataset.openPost);}});
function serverApprovalRows(){return serverPosts.filter(post=>post.status==='pending_approval').map(post=>{const client=clients.find(item=>item.id===post.clientId),style=clientStyle(client),name=client?.name||'Client';return{serverId:post.id,title:post.title||'Untitled post',client:name,channel:post.jobs.map(jobLabel).join(', '),text:post.text||'',by:post.source==='autopilot'?'Autopilot':post.createdBy===activeUser?.id?'You':(teamNames[post.createdBy]||'A teammate'),status:'In Review',initials:post.source==='autopilot'?'AP':client?.initials||name.slice(0,2),color:style.color,scheduledFor:post.scheduledFor,media:post.media||[],autopilot:post.source==='autopilot',clientStatus:post.clientStatus};});}
function drawApprovals(){const el=$('#approval-table');if(!el)return;const cloud=cloudFeaturesAvailable(),rows=cloud?serverApprovalRows():approvals,count=$('.nav-item[data-view="approvals"] .nav-count');if(count){const waiting=rows.filter(item=>item.status!=='Approved').length;count.textContent=waiting;count.hidden=!waiting;}if(!rows.length){el.innerHTML=`<p class="approval-empty">${cloud?'Nothing is waiting for approval.':'No sample approvals.'}</p>`;return;}el.innerHTML=rows.map((item,index)=>`<div class="approval-table-row" data-approval="${index}"><div class="approval-post"><div class="client-avatar ${item.color}">${escapeHtml(item.initials)}</div><div><b>${escapeHtml(item.title)}</b><small>${item.serverId?`${item.autopilot?'Autopilot · ':''}${whenHtml(item.scheduledFor)}`:'Sample approval'}</small>${item.text&&item.text.trim()!==item.title.trim()?`<p class="approval-snippet">${escapeHtml(item.text)}</p>`:''}${item.media?.length?mediaThumbsHtml(item.media,{max:4,className:'small'}):''}</div></div><div class="approval-client"><b>${escapeHtml(item.client)}</b><small>${escapeHtml(item.channel)}</small></div><div class="submitted-by">${escapeHtml(item.by)}</div><div><span class="status review">${escapeHtml(item.status)}</span>${item.clientStatus?`<small class="client-verdict ${item.clientStatus==='approved'?'good':'bad'}">${item.clientStatus==='approved'?'Client approved':'Client wants changes'}</small>`:''}</div><div class="approval-actions"><button class="approve" data-approve="${index}" ${item.status==='Approved'?'disabled':''}>${icon('check')}Approve</button>${item.serverId?`<button data-reject="${index}">Changes</button><button data-review="${index}">Review</button>`:`<button data-edit="${index}">Review</button>`}</div></div>`).join('');
$$('[data-approve]',el).forEach(button=>button.addEventListener('click',async()=>{const item=rows[+button.dataset.approve];if(item.serverId){button.disabled=true;await approveServerPost(item.serverId);button.disabled=false;return;}item.status='Approved';scheduleWorkspaceSave();toast(`“${item.title}” sample approval updated.`);renderApprovals();}));
$$('[data-reject]',el).forEach(button=>button.addEventListener('click',()=>rejectServerPost(rows[+button.dataset.reject].serverId)));
$$('[data-review]',el).forEach(button=>button.addEventListener('click',()=>openPostDialog(rows[+button.dataset.review].serverId)));
$$('[data-edit]',el).forEach(button=>button.addEventListener('click',()=>{const item=rows[+button.dataset.edit];showView('composer');$('#post-copy').value=`${item.title}\n\nAdd your caption here…`;selectVariant('all');scheduleDraftSave();toast('Draft opened in Publishing Studio');}));}
function renderApprovals(){drawApprovals();renderBulkBar();}

// Social account connections: direct sign-in with Meta, LinkedIn, and Pinterest; Ayrshare for other networks.
const DIRECT_PROVIDERS={facebook:'meta',instagram:'meta',linkedin:'linkedin',pinterest:'pinterest',twitter:'x',youtube:'google',tiktok:'tiktok',threads:'threads',bluesky:'bluesky',mastodon:'mastodon'};
const PROVIDER_NAMES={meta:'Facebook & Instagram',linkedin:'LinkedIn',pinterest:'Pinterest',x:'X',google:'YouTube',tiktok:'TikTok',threads:'Threads',bluesky:'Bluesky',mastodon:'Mastodon'};
let socialIntegrations=null,oauthSessionId=null,oauthPoll=null,oauthChecking=null;
function accountStateHtml(account,platform){const provider=DIRECT_PROVIDERS[platform],direct=account?.provider==='direct',days=account?.expiresAt?(Date.parse(account.expiresAt)-Date.now())/86400000:Infinity;if(direct&&account.status==='needs_reauth')return{state:'Reconnect needed',cls:'warning',detail:account.error||'The sign-in expired or was revoked.',buttons:`<button class="secondary-button" type="button" data-connect-provider="${provider}" data-connect-variant="${account.app==='pages'?'pages':''}">Reconnect</button>`};if(direct&&account.linked)return{state:'Connected',cls:'connected',detail:`${account.displayName||account.username||'Connected'}${platform==='pinterest'&&account.boardId?` · Board: ${(account.boards||[]).find(board=>board.id===account.boardId)?.name||'chosen'}`:''}${platform==='linkedin'?account.kind==='organization'?' · Company Page':' · Personal profile':''}${days<14?` · Reconnect by ${new Date(account.expiresAt).toLocaleDateString('en-US',{month:'short',day:'numeric'})}`:''}`,buttons:`<button class="text-button" type="button" data-connect-provider="${provider}" data-connect-variant="${account.app==='pages'?'pages':''}">Switch</button><button class="text-button" type="button" data-disconnect-platform="${platform}">Disconnect</button>`};if(account?.linked)return{state:'Connected',cls:'connected',detail:`${account.displayName||account.username||'Connected'} · via Ayrshare`,buttons:''};if(provider&&(account?.directAvailable||!socialIntegrations))return{state:'Not connected',cls:'disconnected',detail:`Connect to publish and to bring in ${platformLabel(platform)} posts and followers.`,buttons:account?.directAvailable?(platform==='linkedin'?`<button class="primary-button" type="button" data-connect-provider="linkedin">Connect your profile</button>${socialIntegrations?.linkedinPages?'<button class="secondary-button" type="button" data-connect-provider="linkedin" data-connect-variant="pages">Connect a company Page</button>':''}`:`<button class="primary-button" type="button" data-connect-provider="${provider}">Connect</button>`):''};if(account?.ayrshareAvailable)return{state:'Not connected',cls:'disconnected',detail:'Connect with “Connect via Ayrshare”',buttons:''};return{state:'Not set up',cls:'disconnected',detail:provider?`Add the ${PROVIDER_NAMES[provider]} app keys on the server to connect.`:'Needs Ayrshare on the server.',buttons:''};}
function renderSocialAccountCards(accounts=[]){const grid=$('#social-account-grid');if(!grid)return;const shown=SOCIAL_NETWORKS.filter(([platform])=>{if(platform==='instagram_story'||platform==='facebook_story')return false;const account=accounts.find(item=>item.platform===platform);return DIRECT_PROVIDERS[platform]||account?.linked||account?.ayrshareAvailable;});// Connected accounts (and ones that need reconnecting) get full cards; the rest sit in a compact row to add.
const card=([platform,label,icon])=>{const account=accounts.find(item=>item.platform===platform),view=accountStateHtml(account,platform);return{view,html:`<div class="social-account-card ${account?.linked?'is-connected':'is-unlinked'} state-${view.cls}"><div class="social-account-head"><span class="social-platform-icon ${platform}">${icon}</span><b>${label}</b><span class="social-account-state ${view.cls}">${view.state}</span></div><p class="social-account-detail" title="${escapeHtml(view.detail)}">${escapeHtml(view.detail)}</p>${view.buttons?`<div class="social-account-buttons">${view.buttons}</div>`:''}</div>`,compact:`<div class="social-add-item"><span class="social-platform-icon ${platform}">${icon}</span><b>${label}</b>${view.buttons?`<div class="social-account-buttons">${view.buttons}</div>`:`<small>${escapeHtml(view.state)}</small>`}</div>`};};
const cards=shown.map(card),main=cards.filter(item=>item.view.cls!=='disconnected'),rest=cards.filter(item=>item.view.cls==='disconnected');
grid.innerHTML=main.map(item=>item.html).join('')+(rest.length?`<section class="social-add" aria-label="Add a network"><h3>${main.length?'Add a network':'Connect a network'}</h3><p class="option-hint">Connect to publish and to bring in posts and followers.</p><div class="social-add-grid">${rest.map(item=>item.compact).join('')}</div></section>`:'');const ayrshare=$('#connect-social-accounts');if(ayrshare){ayrshare.hidden=!socialIntegrations?.ayrshare;ayrshare.innerHTML=icon('plus')+'Connect via Ayrshare';}const note=$('.integration-note');if(note)note.textContent=`Each network connects directly through its own sign-in; Bluesky uses an app password and Mastodon an access token. Facebook and Instagram Stories use those same connections. ${socialIntegrations?.ayrshare?'Other networks connect through Ayrshare.':'For a network that isn’t connected, SignalDesk can remind you at the scheduled time with the copy ready to paste (“Remind me to post on” in the Publishing Studio).'}`;}
async function refreshSocialAccounts(){const client=selectedClient('#accounts-client-select');if(!client){const status=$('#social-accounts-status');if(status&&!clients.length&&cloudFeaturesAvailable())status.innerHTML='Accounts are connected per client. <button type="button" class="text-button" data-add-first-client>Add your first client</button> to start.';return;}const status=$('#social-accounts-status');if(!cloudFeaturesAvailable()){if(status)status.textContent='Sign in and configure Supabase to connect social accounts.';renderSocialAccountCards();return;}if(status)status.textContent='Checking linked accounts…';try{const data=await callSocialApi({action:'accounts',clientId:client.id});socialIntegrations=data.integrations||null;socialAccountCache.set(client.id,data.accounts||[]);renderSocialAccountCards(data.accounts||[]);const linked=(data.accounts||[]).filter(account=>account.linked&&!account.via).length,reauth=(data.accounts||[]).filter(account=>account.status==='needs_reauth').length;if(status)status.textContent=`${linked} connected network${linked===1?'':'s'} for ${client.name}.${reauth?` ${reauth} need${reauth===1?'s':''} reconnecting.`:''}${data.warning?` ${data.warning}`:''}`;}catch(error){renderSocialAccountCards(socialAccountCache.get(client.id)||[]);if(status)status.textContent=error.message;}}
// Sign-in pages each network's connect button may open; anything else is refused.
const OAUTH_HOSTS=['www.facebook.com','www.linkedin.com','www.pinterest.com','x.com','twitter.com','accounts.google.com','www.tiktok.com','threads.net','www.threads.net','threads.com','www.threads.com'];
async function startDirectConnect(provider,variant=''){if(!selectedClient('#accounts-client-select')&&!clients.length){toast('Add a client first, then connect their accounts.');openClientDialog();return;}const client=selectedClient('#accounts-client-select');if(!client)return;const popup=window.open('about:blank','signaldesk-connect','width=620,height=760');if(!popup){toast('Allow pop-ups to connect accounts.');return;}try{const result=await callSocialApi({action:'oauth-start',clientId:client.id,provider,...(variant?{variant}:{})}),target=new URL(result.url);if(target.protocol!=='https:'||!OAUTH_HOSTS.includes(target.hostname))throw new Error('The sign-in address looks wrong, so it was blocked.');oauthSessionId=result.sessionId;popup.location.href=target.href;clearInterval(oauthPoll);oauthPoll=setInterval(()=>{if(popup.closed){clearInterval(oauthPoll);if(oauthSessionId)checkOauthSession(oauthSessionId);}},800);}catch(error){popup.close();$('#social-accounts-status').textContent=error.message;toast(error.message);}}
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.data?.type!=='signaldesk-oauth')return;if(event.data.sessionId&&event.data.sessionId===oauthSessionId)checkOauthSession(oauthSessionId);else if(!event.data.ok&&event.data.message)toast(event.data.message);});
async function checkOauthSession(id){if(oauthChecking===id)return;oauthChecking=id;try{const data=await callSocialApi({action:'oauth-session',sessionId:id});if(data.status==='authorized'){oauthSessionId=null;openConnectChooser(id,data);}else if(data.status==='failed'){oauthSessionId=null;toast(data.error||'The sign-in didn’t finish.');$('#social-accounts-status').textContent=data.error||'';}}catch(error){toast(error.message);}finally{oauthChecking=null;}}
function openConnectChooser(sessionId,data){const dialog=$('#connect-dialog');if(!dialog)return;const client=clients.find(item=>item.id===data.clientId),groups={};data.candidates.forEach(candidate=>(groups[candidate.platform]||=[]).push(candidate));dialog.dataset.session=sessionId;$('#connect-intro').textContent=`Pick the accounts to use for ${client?.name||'this client'}. You can connect one account per network.`;$('#connect-message').textContent='';$('#connect-options').innerHTML=Object.entries(groups).map(([platform,list])=>`<fieldset class="pref-group connect-group"><legend class="field-label">${escapeHtml(platformLabel(platform))}</legend>${list.map((candidate,index)=>{const noBoards=platform==='pinterest'&&!candidate.boards?.length;return `<label class="option-toggle connect-choice${noBoards?' is-blocked':''}"><input type="radio" name="pick-${platform}" value="${escapeHtml(candidate.key)}" ${index===0&&!noBoards?'checked':''} ${noBoards?'disabled':''}><span><b>${escapeHtml(candidate.displayName||candidate.username||candidate.externalId)}</b>${noBoards?`<small>This account has no boards yet, and Pins need one. <a href="https://www.pinterest.com/${encodeURIComponent(candidate.username||'')}/_saved/" target="_blank" rel="noopener">Create a board on Pinterest ↗</a>, then connect again.</small>`:candidate.note?`<small>${escapeHtml(candidate.note)}</small>`:''}</span></label>${platform==='pinterest'&&candidate.boards?.length?`<select class="field" data-board-for="${escapeHtml(candidate.key)}" aria-label="Board for new Pins">${candidate.boards.map(board=>`<option value="${escapeHtml(board.id)}">${escapeHtml(board.name)}</option>`).join('')}</select>`:''}`;}).join('')}<label class="option-toggle connect-choice"><input type="radio" name="pick-${platform}" value="" ${list.every(candidate=>platform==='pinterest'&&!candidate.boards?.length)?'checked':''}><span>Don’t connect ${escapeHtml(platformLabel(platform))}</span></label></fieldset>`).join('');dialog.showModal();}
$('#connect-form')?.addEventListener('submit',async event=>{event.preventDefault();const dialog=$('#connect-dialog'),selections=$$('#connect-options input[type=radio]:checked').filter(input=>input.value).map(input=>{const board=$(`[data-board-for="${CSS.escape(input.value)}"]`);return board?{key:input.value,boardId:board.value}:{key:input.value};});if(!selections.length){$('#connect-message').textContent='Choose at least one account.';return;}try{const result=await callSocialApi({action:'oauth-finish',sessionId:dialog.dataset.session,selections});dialog.close();toast(`Connected ${result.connected.map(platformLabel).join(', ')}.`);refreshSocialAccounts();}catch(error){$('#connect-message').textContent=error.message;}});
$('#connect-cancel')?.addEventListener('click',()=>$('#connect-dialog').close());
$('#social-account-grid')?.addEventListener('click',async event=>{const connect=event.target.closest('[data-connect-provider]');if(connect){if(['bluesky','mastodon'].includes(connect.dataset.connectProvider)){openCredentialConnect(connect.dataset.connectProvider);return;}startDirectConnect(connect.dataset.connectProvider,connect.dataset.connectVariant||'');return;}const disconnect=event.target.closest('[data-disconnect-platform]');if(!disconnect)return;const client=selectedClient('#accounts-client-select'),platform=disconnect.dataset.disconnectPlatform;const card=disconnect.closest('.social-account-card');card?.classList.add('pending-disconnect');showUndo(`Disconnecting ${client?.name||'this client'}’s ${platformLabel(platform)}. Scheduled posts to it will fail until you reconnect.`,{run:async()=>{const result=await callSocialApi({action:'disconnect',clientId:client.id,platform});card?.classList.remove('pending-disconnect');toast(result.waitingPosts?`${platformLabel(platform)} disconnected. ${result.waitingPosts} scheduled post${result.waitingPosts===1?'':'s'} to it will fail until you reconnect.`:`${platformLabel(platform)} disconnected.`);refreshSocialAccounts();},onUndo:()=>card?.classList.remove('pending-disconnect'),undoneMessage:`${platformLabel(platform)} stays connected.`});});

// Pinterest options in the composer.
function renderPinterestOptions(platforms){const group=$('#pinterest-options');if(!group)return;const on=platforms.includes('pinterest');group.hidden=!on;if(!on)return;const client=selectedClient('#client-select'),account=(socialAccountCache.get(client?.id)||[]).find(item=>item.platform==='pinterest'),boards=account?.boards||[],select=$('#pin-board'),key=boards.map(board=>board.id).join(',');if(select.dataset.key!==key){select.dataset.key=key;select.innerHTML=`<option value="">${boards.length?`Default board${account?.boardId?` (${escapeHtml(boards.find(board=>board.id===account.boardId)?.name||'chosen when connecting')})`:''}`:'Board chosen when connecting'}</option>`+boards.map(board=>`<option value="${escapeHtml(board.id)}">${escapeHtml(board.name)}</option>`).join('');}select.value=boards.some(board=>board.id===postOptions.pinterest.boardId)?postOptions.pinterest.boardId:'';if($('#pin-title').value!==postOptions.pinterest.title)$('#pin-title').value=postOptions.pinterest.title;if($('#pin-link').value!==postOptions.pinterest.link)$('#pin-link').value=postOptions.pinterest.link;const video=draftVideo(),still=Boolean(video&&postOptions.pinterest.coverAsImage);$('#pin-cover-row').hidden=!video;$('#pin-cover-image').checked=still;$('#pin-media-hint').textContent=!still?'Pins take up to 5 images or one video.':draftCover()?.url?'The cover frame goes up as a still image instead of the video.':'Choose a frame or upload a cover under the video first.';$('#pinterest-summary').textContent=[postOptions.pinterest.title&&'Title',postOptions.pinterest.link&&'Link',postOptions.pinterest.boardId&&'Board',still&&'Cover as image'].filter(Boolean).join(' · ')||'Defaults';}
// Assigned to: who's looking after this post. Anyone on the team can set it; the person is told.
function postAssignHtml(post){const people=Object.entries(teamNames||{});if(!people.length||!cloudFeaturesAvailable())return '';const me=activeUser?.id,current=String(post.assignedTo||'');if(current&&!teamNames[current])people.push([current,'A former teammate']);
  const options=[['','Nobody'],...people.sort((a,b)=>a[1].localeCompare(b[1])).map(([id,name])=>[id,id===me?`${name} (you)`:name])];
  return `<label class="post-assign"><span>Assigned to</span><select class="field inline-select" data-assign-post aria-label="Assigned to">${options.map(([id,label])=>`<option value="${escapeHtml(id)}" ${current===id?'selected':''}>${escapeHtml(label)}</option>`).join('')}</select></label>`;}
document.addEventListener('change',async event=>{const select=event.target.closest?.('[data-assign-post]');if(!select||!openPostId)return;const to=select.value||null;select.disabled=true;const result=await postAction({action:'assign-post',postId:openPostId,userId:to},to?`Assigned to ${to===activeUser?.id?'you':teamNames[to]||'a teammate'}.`:'Nobody is assigned now.');if(!result)select.disabled=false;});
// Repeating posts: the original and its repeats form a series. Its details say so, and canceling offers
// just this one or this and the later ones (canceling the original alone used to take every repeat with it).
function postSeries(post){const root=post.parentId||post.id,members=serverPosts.filter(item=>(item.id===root||item.parentId===root)&&item.status!=='canceled').sort((a,b)=>Date.parse(a.scheduledFor)-Date.parse(b.scheduledFor)),original=serverPosts.find(item=>item.id===root);
  return{members,original,total:original?.options?.reposts?.repeat?original.options.reposts.repeat+1:members.length,later:members.filter(item=>Date.parse(item.scheduledFor)>=Date.parse(post.scheduledFor))};}
function postSeriesHtml(post){if(!post.parentId&&!post.options?.reposts)return '';const series=postSeries(post);if(series.members.length<2&&!post.parentId)return '';const next=series.later.find(item=>item.id!==post.id);
  return `<p class="post-series">${icon('repeat','ico-inline')}${post.parentId?'A repeat in a series':'Repeats'}${series.total>1?` · ${series.total} in all`:''}${next?` · next ${escapeHtml(new Date(next.scheduledFor).toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'}))}`:''}</p>`;}
function cancelButtonsHtml(post,withdraw){const series=post.parentId||post.options?.reposts?postSeries(post):null;if(withdraw||!series||series.later.length<2)return `<button class="text-button danger" type="button" data-cancel-post${series&&!post.parentId?' data-cancel-scope="following"':''}>${withdraw?'Withdraw post':'Cancel post'}</button>`;
  return `<button class="text-button danger" type="button" data-cancel-post data-cancel-scope="one">Cancel this one</button><button class="text-button danger" type="button" data-cancel-post data-cancel-scope="following">Cancel this and ${series.later.length-1} later</button>`;}
// A/B test results in a post's details: each version's caption, engagements, and audience, and which did
// better once both have numbers (by engagement rate when both report an audience, else engagements).
function abTotals(post){let engagements=null,audience=null;for(const job of post.jobs||[]){const m=job.metrics||{};if(typeof m.engagements==='number')engagements=(engagements||0)+m.engagements;const reach=typeof m.reach==='number'?m.reach:typeof m.views==='number'?m.views:null;if(reach!==null)audience=(audience||0)+reach;}return{engagements,audience,rate:engagements!==null&&audience?Math.round(engagements/audience*1000)/10:null};}
function abWinner(a,b){if(a.rate!==null&&b.rate!==null&&a.rate!==b.rate)return a.rate>b.rate?'A':'B';if(a.engagements!==null&&b.engagements!==null&&a.engagements!==b.engagements)return a.engagements>b.engagements?'A':'B';return '';}
function abCompareHtml(post){const test=post.options?.abTest;if(!test)return '';const other=serverPosts.find(item=>item.id!==post.id&&item.options?.abTest?.group===test.group&&item.status!=='canceled');
  const rows=[post,other].filter(Boolean).sort((x,y)=>x.options.abTest.version.localeCompare(y.options.abTest.version)),totals=Object.fromEntries(rows.map(row=>[row.options.abTest.version,abTotals(row)])),winner=totals.A&&totals.B&&rows.every(row=>row.status==='published'||row.status==='partial')?abWinner(totals.A,totals.B):'';
  const cell=(row)=>{const t=totals[row.options.abTest.version],when=new Date(row.scheduledFor).toLocaleDateString('en-US',{month:'short',day:'numeric'});return `<div class="ab-cell${winner===row.options.abTest.version?' ab-win':''}"><b>Version ${row.options.abTest.version}${row.id===post.id?' (this post)':''}${winner===row.options.abTest.version?' · did better':''}</b><p>${escapeHtml((row.text||'').slice(0,140))}${(row.text||'').length>140?'…':''}</p><small>${escapeHtml(when)} · ${t.engagements===null?'No results yet':`${compactNumber(t.engagements)} engagements${t.audience?` · ${compactNumber(t.audience)} reached · ${t.rate}%`:''}`}</small></div>`;};
  return `<div class="ab-compare"><h3>A/B test</h3><div class="ab-grid">${rows.map(cell).join('')}${other?'':'<div class="ab-cell"><b>The other version</b><p class="option-hint">Not on the calendar right now, or canceled.</p></div>'}</div></div>`;}
document.addEventListener('click',async event=>{const copy=event.target.closest('[data-copy-caption]');if(copy&&openPostId){const post=serverPosts.find(item=>item.id===openPostId);if(!post)return;const text=post.platformContent?.[copy.dataset.copyCaption]?.text??post.text??'';try{await navigator.clipboard.writeText(text);toast('Caption copied.');}catch{toast('Couldn’t copy. Select the caption and copy it.');}return;}
  const phone=event.target.closest('[data-send-phone]');if(phone&&openPostId){phone.disabled=true;try{await callSocialApi({action:'send-to-phone',postId:openPostId});toast('Sent. Tap the notification on your phone to open this post.');}catch(error){toast(error.message);}finally{phone.disabled=false;}}});
// Bluesky and Mastodon: no sign-in page to send people to, so a short form asks for the account's
// handle and app password (Bluesky) or server and access token (Mastodon).
function openCredentialConnect(platform){const client=selectedClient('#accounts-client-select');if(!client){toast('Choose a client first.');return;}let dialog=$('#credential-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='credential-dialog';dialog.className='auth-dialog';dialog.setAttribute('aria-labelledby','credential-title');document.body.append(dialog);}
  const bsky=platform==='bluesky';
  dialog.innerHTML=`<form class="auth-form" id="credential-form"><h2 id="credential-title">Connect ${bsky?'Bluesky':'Mastodon'} for ${escapeHtml(client.name)}</h2>${bsky?`<label class="field-label" for="cred-a">Handle</label><input class="field" id="cred-a" required autocomplete="off" placeholder="yourname.bsky.social"><label class="field-label" for="cred-b">App password</label><input class="field" id="cred-b" required autocomplete="off" placeholder="xxxx-xxxx-xxxx-xxxx"><p class="option-hint">Make one in Bluesky: Settings → Privacy and security → App passwords. It can post but can’t change the account’s password, and you can delete it any time.</p>`:`<label class="field-label" for="cred-a">Server</label><input class="field" id="cred-a" required autocomplete="off" placeholder="mastodon.social"><label class="field-label" for="cred-b">Access token</label><input class="field" id="cred-b" required autocomplete="off" placeholder="Paste the token"><p class="option-hint">On your Mastodon server: Preferences → Development → New application. Name it SignalDesk, keep the read and write scopes, save, then copy “Your access token”.</p>`}<p class="auth-message" id="credential-message" role="status"></p><div class="confirm-actions"><button class="text-button" type="button" data-close-credential>Cancel</button><button class="primary-button" type="submit">Connect</button></div></form>`;
  dialog.showModal();$('#cred-a').focus();
  dialog.querySelector('[data-close-credential]').addEventListener('click',()=>dialog.close());
  $('#credential-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter||$('#credential-form button[type=submit]'),message=$('#credential-message'),a=$('#cred-a').value.trim(),b=$('#cred-b').value.trim();button.disabled=true;message.textContent='Checking with '+(bsky?'Bluesky':'Mastodon')+'…';
    try{const result=await callSocialApi({action:'connect-credentials',clientId:client.id,platform,...(bsky?{handle:a,password:b}:{instance:a,token:b})});dialog.close();toast(`Connected ${result.connected.displayName||result.connected.username}.`);refreshSocialAccounts();}
    catch(error){message.textContent=error.message;button.disabled=false;}});}
